<template>
  <div class="ViewNotes post">
    <div class="ViewNotes-mb">
      <div class="title">
        <h1 class="post-title">{{ meta ? meta.title : '' }}</h1>
        <div class="recordTime post-info">
          <img src="@/assets/svg/时间1.svg" alt="">
          <span>{{ meta ? meta.date : '' }}</span>
        </div>
      </div>
      <div class="ViewNotes-content post-content">
        <p v-if="error" class="ViewNotes-error">{{ error }}</p>
        <p v-else-if="loading">加载中…</p>
        <v-md-editor v-else :value="markdown" mode="preview"></v-md-editor>
      </div>
    </div>
  </div>
</template>

<script>
import { mapGetters } from 'vuex'

export default {
  name: 'ViewNotes',
  props: { id: { type: String, default: '' } },
  computed: {
    ...mapGetters('notes', ['currentNote', 'currentMeta', 'loading', 'error']),
    markdown() {
      return (this.currentNote && this.currentNote.markdown) || ''
    },
    meta() {
      return this.currentMeta
    },
  },
  created() {
    this.load()
  },
  watch: {
    id() {
      this.load()
    },
  },
  methods: {
    async load() {
      try {
        await this.$store.dispatch('notes/loadIndex')
        if (this.id) await this.$store.dispatch('notes/selectNote', this.id)
      } catch (error) {
        // 错误已写入 store.error，由模板展示
      }
    },
  },
}
</script>
