import { loadIndex, loadNote } from '../core/notesApi.mjs'

export default {
  namespaced: true,
  state: {
    index: null,
    selectedCatalog: '',
    currentId: '',
    currentNote: null,
    loading: false,
    error: '',
  },
  getters: {
    tree: (state) => (state.index && state.index.tree) || [],
    notes: (state) => (state.index && state.index.notes) || [],
    selectedCatalog: (state) => state.selectedCatalog,
    visibleNotes: (state) => {
      const notes = (state.index && state.index.notes) || []
      const prefix = state.selectedCatalog ? `${state.selectedCatalog}/` : ''
      if (!prefix) return []
      return notes.filter((note) => note.path.startsWith(prefix))
    },
    currentId: (state) => state.currentId,
    currentNote: (state) => state.currentNote,
    currentMeta: (state) => {
      if (!state.index || !state.currentId) return null
      return state.index.notes.find((n) => n.id === state.currentId) || null
    },
    loading: (state) => state.loading,
    error: (state) => state.error,
  },
  mutations: {
    SET_INDEX(state, index) {
      state.index = index
      if (!state.selectedCatalog) {
        const firstFolder = index.tree.find((node) => node.type === 'folder')
        state.selectedCatalog = firstFolder ? firstFolder.path : ''
      }
    },
    SET_SELECTED_CATALOG(state, path) { state.selectedCatalog = path },
    SET_LOADING(state, value) { state.loading = value },
    SET_ERROR(state, message) { state.error = message },
    SET_NOTE(state, payload) {
      state.currentId = payload.id
      state.currentNote = payload.note
    },
  },
  actions: {
    async loadIndex({ commit, state }) {
      if (state.index) return state.index
      commit('SET_ERROR', '')
      try {
        const index = await loadIndex()
        commit('SET_INDEX', index)
        return index
      } catch (error) {
        commit('SET_ERROR', error.message)
        throw error
      }
    },
    async selectNote({ commit }, id) {
      commit('SET_LOADING', true)
      commit('SET_ERROR', '')
      try {
        const markdown = await loadNote(id)
        commit('SET_NOTE', { id, note: { id, markdown } })
        return markdown
      } catch (error) {
        commit('SET_ERROR', error.message)
        throw error
      } finally {
        commit('SET_LOADING', false)
      }
    },
    selectCatalog({ commit }, path) {
      commit('SET_SELECTED_CATALOG', path)
    },
  },
}
