export function createRoutes({ HomePage, SubjectAssembly, ViewNotes, NotFound }) {
  return [
    { name: 'home', path: '/', component: HomePage },
    { name: 'subjectAssembly', path: '/subjectAssembly', component: SubjectAssembly },
    { name: 'blog', path: '/blog', component: SubjectAssembly },
    { name: 'posts', path: '/posts', component: SubjectAssembly },
    {
      name: 'viewNotes',
      path: '/viewNotes',
      component: ViewNotes,
      props(route) {
        return { id: route.query.id || '' }
      },
    },
    { name: 'notFound', path: '*', component: NotFound },
  ]
}
