<template>
  <div class="SubjectAssembly notes-layout">
    <aside class="SubjectAssembly-tree note-sidebar">
      <div class="SubjectAssembly-sideTitle">目录</div>
      <NoteTree
        :nodes="tree"
        :current-id="currentId"
        :selected-catalog="selectedCatalog"
        @select-catalog="selectCatalog"
      />
    </aside>
    <main class="SubjectAssembly-list notes-content">
      <p v-if="error" class="SubjectAssembly-error">{{ error }}</p>
      <NoteList v-else />
    </main>
  </div>
</template>

<script>
import { mapGetters } from 'vuex'
import NoteTree from '@/pages/tree/NoteTree.vue'
import NoteList from '@/pages/home/NoteList.vue'

export default {
  name: 'SubjectAssembly',
  components: { NoteTree, NoteList },
  computed: {
    ...mapGetters('notes', ['tree', 'currentId', 'selectedCatalog', 'error']),
  },
  created() {
    this.loadIndex()
  },
  methods: {
    async loadIndex() {
      try {
        await this.$store.dispatch('notes/loadIndex')
      } catch (error) {
        // 错误已写入 store.error，由模板展示
      }
    },
    selectCatalog(path) {
      this.$store.dispatch('notes/selectCatalog', path)
    },
  },
}
</script>
