import { stripFrontmatter } from './frontmatter.mjs'

const BASE = process.env.BASE_URL || '/'

export const NOTES_BASE = `${BASE}notes/`

export function rewriteAssetBase(markdown, base = BASE) {
  return String(markdown)
    .replace(/\]\(\/notes\//g, `](${base}notes/`)
    .replace(/src="\/notes\//g, `src="${base}notes/`)
}

export async function loadIndex() {
  const res = await fetch(`${NOTES_BASE}notes.index.json`, { cache: 'no-cache' })
  if (!res.ok) throw new Error(`加载笔记索引失败：HTTP ${res.status}`)
  return res.json()
}

export async function loadNote(id) {
  const res = await fetch(`${NOTES_BASE}${encodeURI(String(id))}.md`, { cache: 'no-cache' })
  if (!res.ok) throw new Error(`加载笔记失败：HTTP ${res.status}`)
  const raw = await res.text()
  return rewriteAssetBase(stripFrontmatter(raw))
}
