<template>
  <ul class="NoteTree">
    <li v-for="node in nodes" :key="node.path" class="NoteTree-node">
      <template v-if="node.type === 'folder'">
        <div
          class="NoteTree-folder"
          :class="{ 'is-active': node.path === selectedCatalog }"
          @click="selectFolder(node)"
        >
          <span class="NoteTree-twist">{{ isOpen(node) ? '▾' : '▸' }}</span>
          <span class="NoteTree-name">{{ node.name }}</span>
        </div>
        <NoteTree
          v-show="isOpen(node)"
          :nodes="node.children"
          :current-id="currentId"
          :selected-catalog="selectedCatalog"
          @select-catalog="$emit('select-catalog', $event)"
        />
      </template>
      <div
        v-else
        class="NoteTree-note"
        :class="{ 'is-active': node.id === currentId }"
        @click="open(node)"
      >
        {{ node.title }}
      </div>
    </li>
  </ul>
</template>

<script>
export default {
  name: 'NoteTree',
  props: {
    nodes: { type: Array, default: () => [] },
    currentId: { type: String, default: '' },
    selectedCatalog: { type: String, default: '' },
  },
  data() {
    return { openPaths: [] }
  },
  methods: {
    isOpen(node) {
      return this.openPaths.indexOf(node.path) !== -1
    },
    toggle(node) {
      const i = this.openPaths.indexOf(node.path)
      if (i === -1) this.openPaths.push(node.path)
      else this.openPaths.splice(i, 1)
    },
    selectFolder(node) {
      this.$emit('select-catalog', node.path)
      this.toggle(node)
    },
    open(node) {
      this.$router.push({ path: '/viewNotes', query: { id: node.id } })
    },
  },
}
</script>
